foreach($r in '22308.131','22308.143','22308.144'){
  $raw = agent-browser --session bug6931-4382d7d38d88 network request $r --json 2>&1 | Out-String
  Write-Output "===== $r ====="
  # 请求体 grade 字段
  $gradeLines = ($raw -split "`n") | Where-Object { $_ -match 'grade(Comprehensive|Facility|Order|Clean|Greening)Level' }
  $reqGrade = ($raw | Select-String -Pattern '\\"gradeComprehensiveLevel\\":\\?"[^\\"]*\\?' -AllMatches).Matches.Value | Select-Object -First 3
  Write-Output ("req gradeComprehensiveLevel matches: " + (($reqGrade) -join ' | '))
  # 响应 evalLevel / standardName
  $ev = ($raw | Select-String -Pattern '\\"evalLevel\\":\\?"[^\\"]*\\?' -AllMatches).Matches.Value | Group-Object | ForEach-Object { "$($_.Name) x$($_.Count)" }
  Write-Output ("resp evalLevel: " + (($ev) -join ' | '))
  $sn = ($raw | Select-String -Pattern '\\"standardName\\":\\?"[^\\"]*\\?' -AllMatches).Matches.Value | Group-Object | ForEach-Object { "$($_.Name) x$($_.Count)" }
  Write-Output ("resp standardName: " + (($sn) -join ' | '))
}

